/*
 * Rabbit breeding calculators for mintwavestudio.com.
 *
 * The dates follow the Nestbox app (nestbox/lib/domain/breeding.dart): kindling due on day 31
 * (28–35 normal, late from day 33), palpation on day 12, nest box in on day 28, nest box out
 * 21 days after kindling, litter weighed on day 21, weaning at 8 weeks by default.
 * Pages are generated by nestbox/tools/web/site_pages.py.
 *
 * Mount: <div data-nb-calc="gestation|litter|pedigree"></div>
 * Text:  <script type="application/json" id="nb-i18n">{...}</script>
 * Dates are handled as UTC day numbers, so daylight saving changes never shift a date.
 */
(function () {
  "use strict";

  /* ------------------------------------------------------------------ maths (same as the app) */

  const DAY = 86400000;
  const dayNum = iso => {
    const m = /^(\d{4})-(\d{2})-(\d{2})$/.exec(iso || "");
    return m ? Math.round(Date.UTC(+m[1], +m[2] - 1, +m[3]) / DAY) : null;
  };
  const isoOf = n => new Date(n * DAY).toISOString().slice(0, 10);
  const addDays = (iso, d) => isoOf(dayNum(iso) + d);
  const daysBetween = (a, b) => dayNum(b) - dayNum(a);

  const DUE_DAY = 31, LATE_DAY = 33, EARLIEST = 28, LATEST = 35;
  const PALPATE_DAY = 12, NEST_BOX_DAY = 28;
  const NEST_OUT_DAY = 21, WEIGH_DAY = 21, EYES_DAY = 10;

  /* Steps of one breeding, as [key, day after the breeding]. */
  const GESTATION_STEPS = [["palpate", PALPATE_DAY], ["nestBox", NEST_BOX_DAY], ["earliest", EARLIEST],
    ["due", DUE_DAY], ["late", LATE_DAY], ["vet", LATEST]];

  function kindling(bred) {
    return { due: addDays(bred, DUE_DAY), earliest: addDays(bred, EARLIEST), latest: addDays(bred, LATEST),
      palpate: addDays(bred, PALPATE_DAY), nestBox: addDays(bred, NEST_BOX_DAY), late: addDays(bred, LATE_DAY) };
  }

  /* Steps of a litter, as [key, day after kindling]; weaning in whole weeks (4–12). */
  function litterSteps(weanWeeks) {
    const w = Math.max(4, Math.min(12, Math.round(weanWeeks || 8))) * 7;
    return [["eyes", EYES_DAY], ["nestOut", NEST_OUT_DAY], ["weigh", WEIGH_DAY], ["wean", w], ["sex", w]];
  }

  const api = { dayNum, isoOf, addDays, daysBetween, kindling, litterSteps, GESTATION_STEPS, DUE_DAY, LATE_DAY };
  if (typeof module !== "undefined" && module.exports) {
    module.exports = api;
    return;
  }

  /* ------------------------------------------------------------------ browser UI */

  const i18nEl = document.getElementById("nb-i18n");
  if (!i18nEl) return;
  const T = JSON.parse(i18nEl.textContent);
  const lang = document.documentElement.lang || "en";

  const esc = s => String(s ?? "").replace(/[&<>"']/g, c => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c]));
  const fill = (s, v) => String(s).replace(/\{(\w+)\}/g, (m, k) => (k in v ? v[k] : m));
  const store = {
    get(k) { try { return localStorage.getItem(k); } catch (e) { return null; } },
    set(k, v) { try { localStorage.setItem(k, v); } catch (e) { /* private mode */ } }
  };
  const params = new URLSearchParams(location.search);
  const todayIso = () => {
    const d = new Date();
    return isoOf(Math.round(Date.UTC(d.getFullYear(), d.getMonth(), d.getDate()) / DAY));
  };
  const fmtLong = new Intl.DateTimeFormat(T.locale || lang, { weekday: "long", day: "numeric", month: "long", year: "numeric", timeZone: "UTC" });
  const fmtShort = new Intl.DateTimeFormat(T.locale || lang, { weekday: "short", day: "numeric", month: "short", timeZone: "UTC" });
  const long = iso => fmtLong.format(new Date(dayNum(iso) * DAY));
  const short = iso => fmtShort.format(new Date(dayNum(iso) * DAY));
  const setUrl = q => { try { history.replaceState(null, "", location.pathname + "?" + q); } catch (e) { /* file:// */ } };

  function actions() {
    return `<div class="calc-actions">
        <button class="btn" type="button" data-act="ics">${esc(T.ics)}</button>
        <button class="btn ghost" type="button" data-act="print">${esc(T.print)}</button>
        <button class="btn ghost" type="button" data-act="copy">${esc(T.copy)}</button>
      </div>
      <p class="calc-status" role="status"></p>`;
  }

  function ics(events, prodName) {
    const stamp = new Date().toISOString().replace(/[-:]/g, "").replace(/\.\d+/, "");
    const clean = s => String(s).replace(/[\\;,]/g, m => "\\" + m).replace(/\n/g, "\\n");
    const lines = ["BEGIN:VCALENDAR", "VERSION:2.0", `PRODID:-//MintWave Studio//${prodName}//EN`, "CALSCALE:GREGORIAN"];
    events.forEach((ev, i) => {
      lines.push("BEGIN:VEVENT",
        `UID:${ev.date.replace(/-/g, "")}-${prodName.replace(/\W/g, "")}-${i}@mintwavestudio.com`,
        `DTSTAMP:${stamp}`,
        `DTSTART;VALUE=DATE:${ev.date.replace(/-/g, "")}`,
        `DTEND;VALUE=DATE:${addDays(ev.date, 1).replace(/-/g, "")}`,
        `SUMMARY:${clean(ev.title)}`,
        `DESCRIPTION:${clean(ev.desc || "")}`,
        "TRANSP:TRANSPARENT", "END:VEVENT");
    });
    lines.push("END:VCALENDAR");
    return lines.join("\r\n") + "\r\n";
  }

  function bindActions(host, icsFn) {
    host.addEventListener("click", e => {
      const act = e.target.closest("[data-act]")?.dataset.act;
      if (!act) return;
      const status = host.querySelector(".calc-status");
      if (act === "print") window.print();
      if (act === "copy" && navigator.clipboard) {
        navigator.clipboard.writeText(location.href).then(() => { if (status) status.textContent = T.copied; }, () => {});
      }
      if (act === "ics" && icsFn) {
        const file = icsFn();
        if (!file) return;
        const a = document.createElement("a");
        a.href = URL.createObjectURL(new Blob([file.text], { type: "text/calendar" }));
        a.download = file.name;
        document.body.appendChild(a);
        a.click();
        a.remove();
        setTimeout(() => URL.revokeObjectURL(a.href), 1000);
        if (status) status.textContent = T.icsDone;
      }
    });
  }

  function timeline(rows, today, dayLabel) {
    return `<ol class="timeline">${rows.map(r => {
      const cls = r.day < today ? "past" : (r.day === today ? "today" : "");
      return `<li class="${cls}"><span class="day">${esc(fill(dayLabel, { d: r.day }))}</span>
        <span class="what">${esc(r.title)}<small>${esc(r.sub)}</small></span>
        <span class="when">${esc(short(r.date))}</span></li>`;
    }).join("")}</ol>`;
  }

  /* ---------------- gestation / kindling date ---------------- */

  function gestation(host) {
    const G = T.gest;
    const init = dayNum(params.get("date")) != null ? params.get("date") : addDays(todayIso(), -10);
    host.innerHTML = `
      <form class="calc" onsubmit="return false">
        <div class="calc-fields">
          <label class="field">${esc(G.fBred)}<input type="date" name="date" required></label>
        </div>
        <div class="calc-result" aria-live="polite"></div>
      </form>`;
    const dateIn = host.querySelector("input[name=date]");
    const out = host.querySelector(".calc-result");
    dateIn.value = init;
    let current = null;

    function render() {
      const d0 = dayNum(dateIn.value) != null ? dateIn.value : null;
      if (!d0) { out.innerHTML = ""; current = null; return; }
      const k = kindling(d0);
      const today = todayIso();
      const day = daysBetween(d0, today);
      const left = daysBetween(today, k.due);
      let status;
      if (day < 0) status = fill(G.before, { n: -day });
      else if (left > 1) status = fill(G.dayOf, { d: day }) + " " + fill(G.dueIn, { n: left });
      else if (left === 1) status = fill(G.dayOf, { d: day }) + " " + G.dueTomorrow;
      else if (left === 0) status = G.dueToday;
      else if (day < LATE_DAY) status = fill(G.dayOf, { d: day });
      else if (day <= LATEST) status = fill(G.dayOf, { d: day }) + " " + G.lateNow;
      else status = G.past;

      const rows = [{ day: 0, title: G.steps.bred, sub: G.hints.bred }]
        .concat(GESTATION_STEPS.map(([key, d]) => ({ day: d, title: G.steps[key], sub: G.hints[key] })));
      rows.forEach(r => { r.date = addDays(d0, r.day); });
      current = { d0, rows };
      const pct = Math.max(0, Math.min(100, day / DUE_DAY * 100));
      out.innerHTML = `
        <div class="result-hero"><span class="label">${esc(G.due)}</span><span class="date">${esc(long(k.due))}</span></div>
        <p class="result-sub">${esc(fill(G.window, { a: short(k.earliest), b: short(k.latest) }))}<br>${esc(status)}</p>
        <div class="progress" aria-hidden="true"><div style="width:${pct.toFixed(1)}%"></div></div>
        ${timeline(rows, day, G.day)}
        ${actions()}`;
      setUrl(new URLSearchParams({ date: d0 }).toString());
    }

    bindActions(host, () => current && {
      name: `kindling-${current.d0}.ics`,
      text: ics(current.rows.slice(1).map(r => ({ date: r.date, title: G.calPrefix + r.title, desc: r.sub })), "Rabbit gestation calculator")
    });
    dateIn.addEventListener("input", render);
    dateIn.addEventListener("change", render);
    render();
  }

  /* ---------------- litter calendar (from kindling) ---------------- */

  function litter(host) {
    const L = T.litter;
    const init = dayNum(params.get("born")) != null ? params.get("born") : addDays(todayIso(), -7);
    const weeksInit = +(params.get("wean") || store.get("nb.wean") || 8);
    host.innerHTML = `
      <form class="calc" onsubmit="return false">
        <div class="calc-fields">
          <label class="field">${esc(L.fBorn)}<input type="date" name="born" required></label>
          <label class="field">${esc(L.fWean)}<select name="wean">
            ${[4, 5, 6, 7, 8, 10, 12].map(w => `<option value="${w}">${esc(fill(L.weeks, { n: w }))}</option>`).join("")}
          </select></label>
        </div>
        <div class="calc-result" aria-live="polite"></div>
      </form>`;
    const form = host.querySelector("form");
    const out = host.querySelector(".calc-result");
    form.elements.born.value = init;
    form.elements.wean.value = [4, 5, 6, 7, 8, 10, 12].includes(weeksInit) ? String(weeksInit) : "8";
    let current = null;

    function render() {
      const d0 = dayNum(form.elements.born.value) != null ? form.elements.born.value : null;
      if (!d0) { out.innerHTML = ""; current = null; return; }
      const weeks = +form.elements.wean.value;
      const today = todayIso();
      const age = daysBetween(d0, today);
      const steps = litterSteps(weeks);
      const rows = [{ day: 0, title: L.steps.born, sub: L.hints.born }]
        .concat(steps.map(([key, d]) => ({ day: d, title: L.steps[key], sub: L.hints[key] })));
      rows.forEach(r => { r.date = addDays(d0, r.day); });
      current = { d0, rows };
      const weanDate = addDays(d0, weeks * 7);
      const ageText = age < 0 ? L.notYet : fill(L.age, { w: Math.floor(age / 7), d: age % 7, n: age });
      const pct = Math.max(0, Math.min(100, age / (weeks * 7) * 100));
      out.innerHTML = `
        <div class="result-hero"><span class="label">${esc(L.weanOn)}</span><span class="date">${esc(long(weanDate))}</span></div>
        <p class="result-sub">${esc(ageText)}</p>
        <div class="progress" aria-hidden="true"><div style="width:${pct.toFixed(1)}%"></div></div>
        ${timeline(rows, age, L.day)}
        ${actions()}`;
      setUrl(new URLSearchParams({ born: d0, wean: String(weeks) }).toString());
      store.set("nb.wean", String(weeks));
    }

    bindActions(host, () => current && {
      name: `litter-${current.d0}.ics`,
      text: ics(current.rows.slice(1).map(r => ({ date: r.date, title: L.calPrefix + r.title, desc: r.sub })), "Rabbit litter calendar")
    });
    form.addEventListener("change", render);
    form.addEventListener("input", render);
    render();
  }

  /* ---------------- printable pedigree (4 generations) ---------------- */

  function pedigree(host) {
    const P = T.ped;
    const KEY = "nb.pedigree";
    let saved = {};
    try { saved = JSON.parse(store.get(KEY) || "{}") || {}; } catch (e) { saved = {}; }
    const fields = ["name", "ear", "variety", "weight", "reg"];
    const gen = i => (i === 0 ? 0 : Math.floor(Math.log2(i + 1)));
    const role = i => {
      if (i === 0) return P.rabbit;
      const g = gen(i), sire = i % 2 === 1;
      return (sire ? P.sire : P.dam) + (g === 1 ? "" : g === 2 ? " · " + P.g2 : " · " + P.g3);
    };
    const box = i => `<div class="nb-ped-box ${i > 0 && i % 2 === 1 ? "sire" : i > 0 ? "dam" : "root"}" style="grid-row:${rowOf(i)};grid-column:${gen(i) + 1}">
        <span class="nb-ped-role">${esc(role(i))}</span>
        <div class="nb-ped-fields">${fields.map(f => `<label class="nb-f-${f}"><span>${esc(P.f[f])}</span><input name="s${i}.${f}" value="${esc(saved[`s${i}.${f}`] || "")}" autocomplete="off"></label>`).join("")}</div>
      </div>`;
    // Rows on an 8-row grid: the rabbit spans all, parents 4 each, grandparents 2, great-grandparents 1.
    function rowOf(i) {
      const g = gen(i), first = (1 << g) - 1, span = 8 >> g, idx = i - first;
      return `${idx * span + 1} / span ${span}`;
    }
    const head = ["rabbitry", "breeder", "date", "sex", "born", "colour"];
    host.innerHTML = `
      <form class="nb-ped" onsubmit="return false">
        <div class="nb-ped-head">
          ${head.map(f => `<label class="field">${esc(P.h[f])}<input name="h.${f}" value="${esc(saved[`h.${f}`] || "")}" autocomplete="off"></label>`).join("")}
        </div>
        <div class="table-wrap"><div class="nb-ped-grid">${Array.from({ length: 15 }, (_, i) => box(i)).join("")}</div></div>
        <p class="nb-ped-sign">${esc(P.sign)} ______________________________</p>
        <div class="calc-actions no-print">
          <button class="btn" type="button" data-act="print">${esc(T.print)}</button>
          <button class="btn ghost" type="button" data-act="clear">${esc(P.clear)}</button>
        </div>
        <p class="calc-status no-print" role="status"></p>
      </form>`;
    const form = host.querySelector("form");
    form.addEventListener("input", () => {
      const data = {};
      [...form.elements].forEach(el => { if (el.name && el.value) data[el.name] = el.value; });
      store.set(KEY, JSON.stringify(data));
    });
    host.addEventListener("click", e => {
      const act = e.target.closest("[data-act]")?.dataset.act;
      if (act === "print") window.print();
      if (act === "clear" && confirm(P.clearAsk)) {
        [...form.elements].forEach(el => { if (el.tagName === "INPUT") el.value = ""; });
        store.set(KEY, "{}");
      }
    });
  }

  const KINDS = { gestation, litter, pedigree };
  document.querySelectorAll("[data-nb-calc]").forEach(el => {
    const fn = KINDS[el.dataset.nbCalc];
    if (fn) fn(el);
  });
})();
